import axios from 'axios';

const api = axios.create({
  baseURL: process.env.REACT_APP_API_URL || 'http://localhost:8000/api',
  headers: { 'Content-Type': 'application/json' },
  timeout: 10000,
});

api.interceptors.response.use(
  (response) => response,
  (error) => {
    const message =
      error.response?.data?.message ||
      error.response?.data?.error ||
      'Une erreur est survenue';
    return Promise.reject(new Error(message));
  }
);

// ── Comptes de test (mock) ──────────────────────────────────────────────────
const MOCK_USERS = [
  { id: 1, name: 'Admin Test',        email: 'admin@hotel.com',        password: 'Admin123!', role: 'admin' },
  { id: 2, name: 'Receptionniste',    email: 'reception@hotel.com',    password: 'Recep123!', role: 'receptionist' },
  { id: 3, name: 'Client Test',       email: 'client@hotel.com',       password: 'Client123!', role: 'client' },
];

const authService = {
  login: async ({ email, password }) => {
    // Simule un délai réseau
    await new Promise(r => setTimeout(r, 500));
    const user = MOCK_USERS.find(u => u.email === email && u.password === password);
    if (!user) throw new Error('Email ou mot de passe incorrect');
    const { password: _, ...safeUser } = user;
    return { token: `mock-token-${user.role}`, user: safeUser };
  },

  register: async ({ name, email, phone, password }) => {
    await new Promise(r => setTimeout(r, 500));
    const exists = MOCK_USERS.find(u => u.email === email);
    if (exists) throw new Error('Cet email est déjà utilisé');
    const newUser = { id: Date.now(), name, email, phone, role: 'client' };
    return { token: `mock-token-client`, user: newUser };
  },

  setAuthHeader: (token) => {
    api.defaults.headers.common['Authorization'] = `Bearer ${token}`;
  },

  removeAuthHeader: () => {
    delete api.defaults.headers.common['Authorization'];
  },
};

export { api };
export default authService;
